{
  "content_version": "1.0.0",
  "blueprint_id": "position_v1-r2-normal",
  "title": "天文社观测资料交接",
  "story": "天文社观测结束后，你需要从观测准备室前往资料室，核对交接记录并复用交接道具，完成关闭前的最后检查。",
  "rooms": {
    "G1": {
      "name": "观测准备室",
      "description": "桌上散落着观测日志和交接清单，墙上贴着值班注意事项，角落放着几个设备箱。"
    },
    "G2": {
      "name": "资料室",
      "description": "资料柜整齐排列，桌面留有一份关闭检查表，等待你完成线路和物品的最后确认。"
    }
  },
  "objects": {
    "obj_key": {
      "name": "交接钥匙",
      "description": "系着天文社徽章的钥匙，可用于开启资料室的部分储物柜，需要循环使用。"
    },
    "obj_code_source": {
      "name": "观测记录页码",
      "description": "观测日志上标着四个页码数字，旁边注明按记录顺序读取。"
    },
    "obj_relation": {
      "name": "交接顺序便签",
      "description": "便签上写着四个读取位置，提示从源资料的第几位开始按序核对。"
    },
    "obj_device_source": {
      "name": "设备使用登记表",
      "description": "登记表列出四台设备的名称，底部有按登记先后读取的提示。"
    },
    "obj_puzzle_1": {
      "name": "记录核对密码锁",
      "description": "档案盒上的密码锁，需要结合日志页码和便签顺序才能打开。"
    },
    "obj_puzzle_2": {
      "name": "设备复位次序盘",
      "description": "圆形复位盘有四个档位，需依照登记表和位置提示排定设备顺序。"
    },
    "obj_puzzle_3": {
      "name": "线路关闭检查板",
      "description": "资料室墙上的线路板，需按关闭检查表逐一确认线路状态。"
    },
    "obj_puzzle_4": {
      "name": "物品归还箱",
      "description": "检查结束后，需要把交接钥匙等物品放回归还箱并确认清单。"
    }
  },
  "parameters": {
    "digits": ["3", "7", "1", "5"],
    "positions": [2, 4, 1, 3],
    "devices": ["device_c", "device_a", "device_d", "device_b"]
  }
}
